def balanced_feature_bucket(
    X,
    n_buckets,
    seed=42
):
    n_features = X.shape[1]

    if n_buckets >= n_features:
        return X.copy()

    rng = np.random.default_rng(seed)

    permutation = rng.permutation(n_features)

    bucket_of_feature = np.empty(
        n_features,
        dtype=int
    )

    bucket_of_feature[permutation] = (
        np.arange(n_features)
        * n_buckets
        // n_features
    )

    bucket_sizes = np.bincount(
        bucket_of_feature,
        minlength=n_buckets
    ).astype(float)

    X_sketch = np.zeros(
        (X.shape[0], n_buckets),
        dtype=float
    )

    for j in range(n_features):

        bucket = bucket_of_feature[j]

        X_sketch[:, bucket] += (
            X[:, j]
            / np.sqrt(bucket_sizes[bucket])
        )

    return X_sketch

