def sparse_jl_features(
    X,
    n_buckets,
    seed=42,
    sparsity=1
):
    X = sp.csr_matrix(X)

    n_features = X.shape[1]
    n_buckets = min(
        int(n_buckets),
        n_features
    )

    if n_buckets >= n_features:
        return X.copy()

    sparsity = int(sparsity)

    if not 1 <= sparsity <= n_buckets // 2:
        raise ValueError(
            f"sparsity must be between 1 and "
            f"{n_buckets // 2}"
        )

    rng = np.random.default_rng(seed)

    assignments = np.empty(
        (sparsity, n_features),
        dtype=int
    )

    for r in range(sparsity):

        permutation = rng.permutation(
            n_features
        )

        assignment = np.empty(
            n_features,
            dtype=int
        )

        assignment[permutation] = (
            np.arange(n_features)
            * n_buckets
            // n_features
        )

        assignments[r] = assignment

    occupancy = np.bincount(
        assignments.reshape(-1),
        minlength=n_buckets
    ).astype(float)

    signs = np.stack([
        rng.choice(
            [-1.0, 1.0],
            size=n_features
        )
        for _ in range(sparsity)
    ])

    weights = (
        signs
        / np.sqrt(
            occupancy[assignments]
        )
    )

    projection = sp.csr_matrix(
        (
            weights.reshape(-1),
            (
                np.tile(
                    np.arange(n_features),
                    sparsity
                ),
                assignments.reshape(-1)
            )
        ),
        shape=(
            n_features,
            n_buckets
        )
    )

    X_sketch = (
        X @ projection
    ).tocsr()

    X_sketch.eliminate_zeros()

    return X_sketch
